begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values ('10000000-0000-4000-8000-000000000001','reconcile-a@example.test'),('10000000-0000-4000-8000-000000000002','reconcile-b@example.test');
insert into auth.sessions(id,user_id) values ('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001'),('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002');
insert into finance.profiles(id,display_name) values ('10000000-0000-4000-8000-000000000001','Synthetic A'),('10000000-0000-4000-8000-000000000002','Synthetic B');
insert into finance.households(id,name) values ('30000000-0000-4000-8000-000000000001','Synthetic A'),('30000000-0000-4000-8000-000000000002','Synthetic B');
insert into finance.household_members(id,household_id,user_id,display_name) values ('40000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Synthetic A'),('40000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','Synthetic B');
insert into finance.reconciliations values ('30000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001',1,'TRANSFER',true);
insert into finance.reconciliation_decisions values ('30000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001',1,'40000000-0000-4000-8000-000000000001','{"synthetic":true}',null);
select ok((select bool_and(relrowsecurity) from pg_class where oid in ('finance.reconciliations'::regclass,'finance.reconciliation_decisions'::regclass,'finance.reconciliation_participants'::regclass,'finance.reconciliation_claims'::regclass,'private.reconciliation_receipts'::regclass,'private.reconciliation_audit'::regclass)),'all new tables have RLS');
select ok(not has_table_privilege('authenticated',v,'INSERT'),'client INSERT withheld '||v) from unnest(array['finance.reconciliations','finance.reconciliation_decisions','finance.reconciliation_participants','finance.reconciliation_claims','private.reconciliation_receipts','private.reconciliation_audit']) v;
select ok(not has_table_privilege('authenticated',v,'UPDATE'),'client UPDATE withheld '||v) from unnest(array['finance.reconciliations','finance.reconciliation_decisions','finance.reconciliation_participants','finance.reconciliation_claims','private.reconciliation_receipts','private.reconciliation_audit']) v;
select ok(not has_table_privilege('authenticated',v,'DELETE'),'client DELETE withheld '||v) from unnest(array['finance.reconciliations','finance.reconciliation_decisions','finance.reconciliation_participants','finance.reconciliation_claims','private.reconciliation_receipts','private.reconciliation_audit']) v;
select ok(not has_function_privilege('anon',v,'EXECUTE'),'anonymous RPC withheld '||v) from unnest(array['api.reconciliation_snapshot()','api.reconcile(jsonb)','private.reconcile(jsonb)']) v;
select ok(not prosecdef,'invoker exposed API '||proname) from pg_proc where oid in ('api.reconciliation_snapshot()'::regprocedure,'api.reconcile(jsonb)'::regprocedure);
select throws_ok($$update finance.reconciliation_decisions set body='{}'$$,'23514','Financial history is immutable.','immutable decision update');
select throws_ok($$insert into finance.reconciliation_decisions values ('30000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001',2,'40000000-0000-4000-8000-000000000002','{}',null)$$,'23503',null,'same-household durable member FK');
select throws_ok($$insert into finance.reconciliation_participants values('30000000-0000-4000-8000-000000000002','50000000-0000-4000-8000-000000000001',1,gen_random_uuid(),gen_random_uuid(),gen_random_uuid())$$,'23503',null,'same-household decision FK');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000002"}',true);
select is((select count(*) from finance.reconciliation_decisions),0::bigint,'direct RLS hides household A decisions');
select is(api.reconciliation_snapshot()->'decisions','[]'::jsonb,'indirect invoker snapshot hides household A');
select throws_ok('insert into finance.reconciliations values(gen_random_uuid(),gen_random_uuid(),1,''TRANSFER'',true)','42501',null,'direct financial relationship write denied');
select is(private.reconcile('{}')->'error'->>'code','INVALID_INPUT','direct private call also validates');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000001"}',true);
select is((select count(*) from finance.reconciliation_decisions),1::bigint,'authorized direct history');
reset role;
update finance.household_members set status='REVOKED' where id='40000000-0000-4000-8000-000000000001';
set local role authenticated;
select is((select count(*) from finance.reconciliation_decisions),0::bigint,'unchanged JWT cannot read after revocation');
reset role;
delete from auth.users where id='10000000-0000-4000-8000-000000000001';
select is((select count(*) from finance.reconciliation_decisions),1::bigint,'Auth deletion retains decisions');
select is((select user_id from finance.household_members where id='40000000-0000-4000-8000-000000000001'),null::uuid,'durable attribution unlinked safely');
select * from finish();
rollback;
